from __future__ import absolute_import, division, print_function,\
    unicode_literals

from builtins import int, object
from future import standard_library
from contextlib import contextmanager

from taf.ul.trs_e2e_fw.lib.remote_connection.telnet_library.telnet_controller import TelnetController
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()
standard_library.install_aliases()


class Serial_Access(object):

    def __init__(self, ssh_session_to_dongle_host):
        self.ssh_session_to_dongle_host = ssh_session_to_dongle_host

    @contextmanager
    def new_serial_2tcp_connection(self, rat, dongle_config_name):
        self.telnet_session = self._open_serial_connection(rat, dongle_config_name)
        try:
            yield
        except Exception:
            logger.debug('Serial Connection Error to dongle USB in {}->{}'.format(rat, dongle_config_name))
            raise
        finally:
            logger.debug('Serial connection closed')
            self._close_serial_connection()

    def _open_serial_connection(self, rat, dongle_config_name):
        remote_port = 9001
        dongle_config_details = get_config_variable(["ue_devices", rat, dongle_config_name])
        remote_host = dongle_config_details.get('remote_ip', '127.0.0.1')
        tty_path = dongle_config_details.get('tty_path', '/dev/ttyUSB1')
        cmd = 'serial2tcp -p {} -l {} -P {} >serial2tcp.log 2>&1 &' \
              ' echo $!'.format(tty_path, remote_host, remote_port)
        logger.debug(cmd)
        (stdin, console_output, stderr) = \
            self.ssh_session_to_dongle_host.exec_command(cmd)
        # logger.debug("stderr:{}".format(stderr))
        self.serail2tcp_process_id = int(console_output.readline())
        logger.debug("Serial to TCP Process ID: {0}".format(self.serail2tcp_process_id))
        telnet_session = TelnetController()
        telnet_session.setup_telnet_remote_access(
            host=remote_host, user=dongle_config_details.get(
                'remote_user', ''),
            password=dongle_config_details.get('remote_password', ''),
            port=remote_port, prompt='', timeout=10)
        return telnet_session

    def _close_serial_connection(self):
        self.telnet_session.teardown_telnet_remote_access()
        cmd = "kill -2 {}".format(self.serail2tcp_process_id)
        logger.debug("Stopping serial2tcp. Command : {}".format(cmd))
        (stdin, console_output, stderr) = self.ssh_session_to_dongle_host.exec_command(cmd)

    def write_command_and_return_output(self, command):
        logger.debug('{}'.format(command))
        output = decode_str(self.telnet_session.execute_command_on_host(command=command, timeout=60, prompt='OK'))
        logger.debug('{}'.format(output))
        return output
